script:
var TIMES = {{times}};
var SPEED = {{speed}};

var codeGroup = document.getElementById('code');
var varGroup = document.getElementById('vars');
var outGroup = document.getElementById('output');
var caption = document.getElementById('caption');
var counter = document.getElementById('counter');

// 左侧：代码块（逐行高亮）
var CODE_LINES = [
  'total = 0',
  'for i in range(' + TIMES + '):',
  '    total = total + i',
  'print(total)'
];

var codeRows = [];
for (var lineIndex = 0; lineIndex < CODE_LINES.length; lineIndex += 1) {
  var y = 34 + lineIndex * 30;
  var bg = Sandbox.svgEl('rect');
  bg.setAttribute('x', '12');
  bg.setAttribute('y', String(y - 16));
  bg.setAttribute('width', '250');
  bg.setAttribute('height', '24');
  bg.setAttribute('rx', '5');
  bg.setAttribute('fill', 'transparent');
  codeGroup.appendChild(bg);

  var text = Sandbox.svgEl('text');
  text.setAttribute('x', '20');
  text.setAttribute('y', String(y));
  text.setAttribute('style', 'font-family:Consolas,Menlo,monospace;font-size:13px;fill:#12233b');
  text.textContent = CODE_LINES[lineIndex];
  codeGroup.appendChild(text);
  codeRows.push(bg);
}

// 右侧：变量表（i / total）
function varRow(label, y, color) {
  var text = Sandbox.svgEl('text');
  text.setAttribute('x', '300');
  text.setAttribute('y', String(y));
  text.setAttribute('style', 'font-family:Consolas,Menlo,monospace;font-size:13px;fill:' + color);
  text.textContent = label;
  varGroup.appendChild(text);
  return text;
}

var iText = varRow('i = —', 50, '#2f6fd0');
var totalText = varRow('total = 0', 80, '#1f9d63');

// 底部：输出区（每次 print 多一行）
var outputLines = [];

function highlightRow(index) {
  for (var i = 0; i < codeRows.length; i += 1) {
    codeRows[i].setAttribute('fill', i === index ? '#e8f0fd' : 'transparent');
  }
}

function addOutput(text) {
  var node = Sandbox.svgEl('text');
  node.setAttribute('x', '300');
  node.setAttribute('y', String(120 + outputLines.length * 22));
  node.setAttribute('style', 'font-family:Consolas,Menlo,monospace;font-size:13px;fill:#12233b');
  node.setAttribute('opacity', '0');
  node.textContent = '> ' + text;
  outGroup.appendChild(node);
  outputLines.push(node);
  return node;
}

Sandbox.play(function () {
  var steps = [];
  var total = 0;

  steps.push({
    targets: codeRows[0],
    duration: 200,
    begin: function () {
      highlightRow(0);
      caption.textContent = '先把累加器 total 清成 0——它负责把每次的结果攒起来。';
      totalText.textContent = 'total = 0';
    }
  });

  for (var n = 0; n < TIMES; n += 1) {
    steps.push({
      targets: codeRows[1],
      duration: 220 * SPEED,
      begin: (function (index) {
        return function () {
          highlightRow(1);
          caption.textContent = '第 ' + (index + 1) + ' 圈：循环变量 i 变成 ' + index + '。';
          iText.textContent = 'i = ' + index;
          counter.textContent = '第 ' + (index + 1) + ' 次';
        };
      })(n)
    });

    steps.push({
      targets: codeRows[2],
      duration: 300 * SPEED,
      begin: (function (index) {
        return function () {
          highlightRow(2);
          total += index;
          caption.textContent = '执行循环体：total = total + i，也就是累加上了 ' + index + '。';
          totalText.textContent = 'total = ' + total;
        };
      })(n),
      complete: function () {
        // 每圈结束闪一下，让「重复」这件事看得出来
        anime({ targets: totalText, scale: [1, 1.1], duration: 140, direction: 'alternate' });
      }
    });
  }

  steps.push({
    targets: codeRows[1],
    duration: 260,
    begin: function () {
      highlightRow(1);
      caption.textContent = 'i 已经走到 ' + TIMES + '，超出了 range(' + TIMES + ')，循环结束。';
      iText.textContent = 'i = ' + TIMES + '（越界，退出）';
    }
  });

  var out = addOutput(String(total));
  steps.push({
    targets: codeRows[3],
    duration: 320,
    begin: function () {
      highlightRow(3);
      caption.textContent = '循环结束后才执行 print：屏幕上是 ' + total + '。注意它只打印了一次。';
    },
    complete: function () {
      anime({ targets: out, opacity: [0, 1], translateX: [-8, 0], duration: 320 });
      Sandbox.progress(1);
    }
  });

  var timeline = anime.timeline({ autoplay: true, easing: 'easeInOutSine' });
  for (var s = 0; s < steps.length; s += 1) timeline.add(steps[s]);
  timeline.play();

  var duration = timeline.duration || 5000;
  return {
    pause: function () { timeline.pause(); },
    play: function () { timeline.play(); },
    restart: function () { timeline.restart(); },
    finished: {
      then: function (resolve) {
        var elapsed = 0;
        var timer = setInterval(function () {
          elapsed += 100;
          if (timeline.completed || elapsed > duration + 800) {
            clearInterval(timer);
            resolve();
          }
          Sandbox.progress(Math.min(1, elapsed / duration));
        }, 100);
      }
    }
  };
});

Sandbox.ready({ template: 'python-loop', times: TIMES });
